@dataclass(frozen=True)
class _LiftedFamilyAddScreen:
    """Safe common-family endpoint for one not-yet-fitted Add.

    The candidate's nonnegative kernel coefficients and its nonnegative
    stacking weight are lifted into one nonnegative coefficient vector.  The
    resulting convex model contains every exact joint child used by the
    rule-effect family objective.  Its certified NLL lower bound therefore
    gives an upper bound on that *family* score; it is never compared with a
    support-local MDL value.
    """

    score_upper_bound: float
    threshold: float
    nll_lower_bound: float
    cuts: int
    certified_non_improving: bool


def _gradient_bundle_lower_bound(
    values: list[float],
    coefficients: list[np.ndarray],
    gradients: list[np.ndarray],
    *,
    free_dimension: int,
) -> float:
    """Return a verified cutting-plane lower bound for a cone GLM.

    Convexity gives, for every stored iterate ``j``,

        f(beta) >= a_j + g_j.T beta,
        a_j = f(beta_j) - g_j.T beta_j.

    Minimizing the maximum of these affine minorants over the coefficient
    cone is a tiny LP.  Its dual chooses simplex weights ``lambda`` satisfying
    zero aggregate gradient on free coordinates and nonnegative aggregate
    gradient on cone coordinates.  Consequently the returned value is a
    global lower bound on the exact fixed-support NLL, not a local quadratic
    approximation.  Excitation/inhibition signs and total-state masks are
    already part of the gradients supplied by the owning candidate design.

    Numerical feasibility is deliberately strict and fail-open.  A candidate
    is never removed when HiGHS cannot produce a finite, rechecked dual point.
    """

    count = len(values)
    if count == 0 or len(coefficients) != count or len(gradients) != count:
        return -math.inf
    dimension = len(gradients[0])
    if not 0 <= int(free_dimension) <= dimension:
        raise ValueError("invalid gradient-bundle free dimension")
    if any(
        coefficient.shape != (dimension,) or gradient.shape != (dimension,)
        for coefficient, gradient in zip(coefficients, gradients, strict=True)
    ):
        raise ValueError("gradient-bundle cut dimension mismatch")
    if any(
        not math.isfinite(value)
        or not np.all(np.isfinite(coefficient))
        or not np.all(np.isfinite(gradient))
        for value, coefficient, gradient in zip(
            values, coefficients, gradients, strict=True
        )
    ):
        return -math.inf

    gradient_matrix = np.ascontiguousarray(np.vstack(gradients), dtype=np.float64)
    # Cheap exact infeasibility tests before starting HiGHS.  A convex
    # combination can have zero free-coordinate gradient only if zero lies in
    # each coordinate's scalar convex hull.  Likewise every cone coordinate
    # needs at least one nonnegative member.  These are necessary (not
    # sufficient) conditions, so failing one can only skip a futile bound
    # attempt; it can never screen a candidate or change an optimization
    # result.  On the Home Credit audit they remove nearly all LP startups.
    if free_dimension:
        free = gradient_matrix[:, : int(free_dimension)]
        if np.any(np.min(free, axis=0) > 0.0) or np.any(np.max(free, axis=0) < 0.0):
            return -math.inf
    if int(free_dimension) < dimension:
        cone_coordinates = gradient_matrix[:, int(free_dimension) :]
        if np.any(np.max(cone_coordinates, axis=0) < 0.0):
            return -math.inf
    intercepts = np.asarray(
        [
            float(value - gradient @ coefficient)
            for value, coefficient, gradient in zip(
                values, coefficients, gradients, strict=True
            )
        ],
        dtype=np.float64,
    )
    if not np.all(np.isfinite(intercepts)):
        return -math.inf
    equality_parts = [np.ones((1, count), dtype=np.float64)]
    equality_rhs = [1.0]
    if free_dimension:
        equality_parts.append(gradient_matrix[:, :free_dimension].T)
        equality_rhs.extend([0.0] * int(free_dimension))
    equality = np.ascontiguousarray(np.vstack(equality_parts), dtype=np.float64)
    rhs = np.asarray(equality_rhs, dtype=np.float64)
    cone = gradient_matrix[:, int(free_dimension) :]
    inequality = -cone.T if cone.shape[1] else None
    inequality_rhs = (
        np.zeros(cone.shape[1], dtype=np.float64) if cone.shape[1] else None
    )
    try:
        result = linprog(
            -intercepts,
            A_ub=inequality,
            b_ub=inequality_rhs,
            A_eq=equality,
            b_eq=rhs,
            bounds=[(0.0, 1.0)] * count,
            method="highs-ds",
            options={
                "presolve": True,
                "primal_feasibility_tolerance": 1.0e-9,
                "dual_feasibility_tolerance": 1.0e-9,
            },
        )
    except (MemoryError, ValueError):
        return -math.inf
    if not result.success or result.x is None:
        return -math.inf
    weights = np.asarray(result.x, dtype=np.float64)
    # HiGHS may return tiny negative coordinates despite explicit [0, 1]
    # bounds.  They cannot be used in a convex dual combination.  Project the
    # positive active face back onto the simplex/free-gradient equalities and
    # discard a face if that exact correction would make a weight negative.
    active = np.flatnonzero(weights > 1.0e-10)
    repaired = np.zeros_like(weights)
    while len(active) >= equality.shape[0]:
        active_equalities = equality[:, active]
        active_weights = np.maximum(weights[active], 0.0)
        residual = rhs - active_equalities @ active_weights
        gram = active_equalities @ active_equalities.T
        try:
            correction = active_equalities.T @ np.linalg.solve(gram, residual)
        except np.linalg.LinAlgError:
            correction = active_equalities.T @ (
                np.linalg.pinv(gram, rcond=np.finfo(np.float64).eps) @ residual
            )
        active_weights += correction
        if float(np.min(active_weights, initial=0.0)) >= -1.0e-12:
            repaired[active] = np.maximum(active_weights, 0.0)
            # A final equality projection removes the rounding introduced by
            # clamping a tolerance-level negative coordinate.
            residual = rhs - active_equalities @ repaired[active]
            try:
                repaired[active] += active_equalities.T @ np.linalg.solve(
                    gram, residual
                )
            except np.linalg.LinAlgError:
                repaired.fill(0.0)
            break
        active = np.delete(active, int(np.argmin(active_weights)))
    weights = repaired
    if not np.any(weights):
        return -math.inf
    # Recheck the actual point used for the bound rather than trusting solver
    # status.  Requiring strictly nonnegative cone correlations avoids turning
    # a tolerance-level inequality violation into an unsafe finite endpoint.
    aggregate = weights @ gradient_matrix
    equality_scale = max(
        1.0,
        float(np.max(np.abs(gradient_matrix[:, :free_dimension]), initial=0.0)),
    )
    equality_tolerance = 4096.0 * np.finfo(np.float64).eps * equality_scale
    if abs(float(np.sum(weights)) - 1.0) > 4096.0 * np.finfo(np.float64).eps:
        return -math.inf
    if (
        free_dimension
        and float(np.max(np.abs(aggregate[:free_dimension]))) > equality_tolerance
    ):
        return -math.inf
    if cone.shape[1] and float(np.min(aggregate[free_dimension:])) < 0.0:
        return -math.inf
    lower = float(weights @ intercepts)
    # Convex combinations of natural gradient duals stay in the conjugate
    # domain.  Jensen gives this affine-envelope value as a conservative dual
    # objective.  Subtract a summation-level ulp allowance before a decision.
    slack = (
        256.0
        * np.finfo(np.float64).eps
        * max(1.0, float(np.sum(np.abs(weights * intercepts))))
    )
    lower -= slack
    primal = min(values)
    return lower if math.isfinite(lower) and lower <= primal + slack else -math.inf


@dataclass(frozen=True)
class _MatrixFreeStateSplice:
    """Exact touched-row decomposition for one total-state Add proposal.

    A total-state Add changes the design only on the new rule's effective
    response rows.  The target likelihood is therefore exactly

        source likelihood - old touched likelihood + new touched likelihood.

    Keeping the source sufficient statistics in place avoids remapping and
    copying every untouched design group merely to reject a one-step
    candidate.  The ordinary canonical matrix builder remains the fail-open
    path for competitive or numerically unresolved proposals.
    """

    source: ModelMatrix
    likelihood: str
    source_to_target: np.ndarray
    old_x: np.ndarray
    new_block: np.ndarray
    dominated_source_columns: np.ndarray
    exposure_weight: np.ndarray
    noevent_weight: np.ndarray
    event_weight: np.ndarray
    warm_beta: np.ndarray
    source_eta: np.ndarray
    old_eta: np.ndarray
    new_eta: np.ndarray
    initial_nll: float
    gradient: np.ndarray
    hessian: np.ndarray
    free_dimension: int
    added_slice: slice
    added_sign: int
    coordinate_signs: np.ndarray
    source_value_device: str = "cpu"
    old_matrix_token: int = 0
    new_matrix_token: int = 0

    @property
    def dimension(self) -> int:
        return int(len(self.warm_beta))

    @property
    def nbytes(self) -> int:
        return int(
            self.source_to_target.nbytes
            + self.old_x.nbytes
            + self.new_block.nbytes
            + self.dominated_source_columns.nbytes
            + self.exposure_weight.nbytes
            + (
                0
                if self.noevent_weight is self.exposure_weight
                else self.noevent_weight.nbytes
            )
            + self.event_weight.nbytes
            + self.warm_beta.nbytes
            + self.old_eta.nbytes
            + self.new_eta.nbytes
            + self.gradient.nbytes
            + self.hessian.nbytes
            + self.coordinate_signs.nbytes
        )

    def with_added_sign(self, sign: int) -> _MatrixFreeStateSplice:
        """Reuse one unsigned geometry for the opposite signed identity."""

        sign = int(sign)
        if sign not in {-1, 1}:
            raise ValueError("state-splice sign must be -1 or +1")
        if sign == self.added_sign:
            return self
        transform = np.ones(self.dimension, dtype=np.float64)
        transform[self.added_slice] = float(sign * self.added_sign)
        return replace(
            self,
            gradient=np.ascontiguousarray(transform * self.gradient),
            hessian=np.ascontiguousarray(
                transform[:, None] * self.hessian * transform[None, :]
            ),
            added_sign=sign,
            coordinate_signs=np.ascontiguousarray(transform * self.coordinate_signs),
        )

    def _loss_sum(self, eta: np.ndarray) -> float:
        return float(
            np.sum(
                loss_value_rows(
                    eta,
                    likelihood=self.likelihood,
                    exposure_weight=self.exposure_weight,
                    noevent_weight=self.noevent_weight,
                    event_weight=self.event_weight,
                )
            )
        )

    def _source_value(self, beta: np.ndarray) -> float:
        result = None
        if is_poisson_likelihood(self.likelihood):
            result = resident_poisson_objective(
                self.source.x,
                beta,
                self.source.exposure_weight,
                self.source.event_weight,
                device=self.source_value_device,
                matrix_token=self.source.resident_token,
                compute_moments=False,
                return_eta=False,
            )
        elif self.likelihood == "first_event_cloglog":
            result = resident_cloglog_objective(
                self.source.x,
                beta,
                self.source.noevent_weight,
                self.source.event_weight,
                device=self.source_value_device,
                matrix_token=self.source.resident_token,
                compute_moments=False,
                return_eta=False,
            )
        if result is not None:
            return float(result[0])
        eta = self.source.x @ beta
        return float(
            np.sum(
                loss_value_rows(
                    eta,
                    likelihood=self.likelihood,
                    exposure_weight=self.source.exposure_weight,
                    noevent_weight=self.source.noevent_weight,
                    event_weight=self.source.event_weight,
                )
            )
        )

    def _objective(
        self,
        beta: np.ndarray,
        source_evaluator: ProjectedDesignEvaluator,
    ) -> tuple[float, np.ndarray, np.ndarray]:
        """Evaluate the exact target model from parent plus touched rows."""
        source_beta = np.ascontiguousarray(
            beta[self.source_to_target], dtype=np.float64
        )
        source_nll, source_gradient, source_hessian = source_evaluator.objective(
            source_beta
        )
        old_eta = self.old_x @ source_beta
        new_eta = old_eta.copy()
        if len(self.dominated_source_columns):
            dominated = self.dominated_source_columns
            new_eta -= self.old_x[:, dominated] @ source_beta[dominated]
        new_eta += float(self.added_sign) * self.new_block @ beta[self.added_slice]
        old_value, old_first, old_second = loss_rows(
            old_eta,
            likelihood=self.likelihood,
            exposure_weight=self.exposure_weight,
            noevent_weight=self.noevent_weight,
            event_weight=self.event_weight,
        )
        new_value, new_first, new_second = loss_rows(
            new_eta,
            likelihood=self.likelihood,
            exposure_weight=self.exposure_weight,
            noevent_weight=self.noevent_weight,
            event_weight=self.event_weight,
        )
        old_gradient, old_hessian = moments(
            self.old_x,
            old_first,
            old_second,
            device=self.source_value_device,
            matrix_token=self.old_matrix_token,
        )
        # ``new_x`` used to be retained as a second touched_rows x
        # target_dimension matrix even though it is exactly old_x with a few
        # dominated columns zeroed plus the M-column new block.  Assemble the
        # same moments blockwise.  This removes the largest proposal
        # allocation while preserving the exact gradient and Fisher matrix.
        new_existing_gradient, new_existing_hessian = moments(
            self.old_x,
            new_first,
            new_second,
            device=self.source_value_device,
        )
        dominated = self.dominated_source_columns
        if len(dominated):
            new_existing_gradient[dominated] = 0.0
            new_existing_hessian[dominated, :] = 0.0
            new_existing_hessian[:, dominated] = 0.0
        block_gradient, block_hessian = moments(
            self.new_block,
            new_first,
            new_second,
            device=self.source_value_device,
            matrix_token=self.new_matrix_token,
        )
        cross = self.old_x.T @ (new_second[:, None] * self.new_block)
        if len(dominated):
            cross[dominated, :] = 0.0
        sign = float(self.added_sign)
        gradient = np.zeros(self.dimension, dtype=np.float64)
        hessian = np.zeros((self.dimension, self.dimension), dtype=np.float64)
        gradient[self.source_to_target] = (
            source_gradient - old_gradient + new_existing_gradient
        )
        hessian[np.ix_(self.source_to_target, self.source_to_target)] = (
            source_hessian - old_hessian + new_existing_hessian
        )
        added_columns = np.arange(self.added_slice.start, self.added_slice.stop)
        gradient[self.added_slice] = sign * block_gradient
        hessian[self.added_slice, self.added_slice] = block_hessian
        hessian[np.ix_(self.source_to_target, added_columns)] = sign * cross
        hessian[np.ix_(added_columns, self.source_to_target)] = sign * cross.T
        nll = float(source_nll - np.sum(old_value) + np.sum(new_value))
        return nll, gradient, 0.5 * (hessian + hessian.T)

    def _value(
        self,
        beta: np.ndarray,
        source_evaluator: ProjectedDesignEvaluator,
    ) -> float:
        source_beta = np.ascontiguousarray(
            beta[self.source_to_target], dtype=np.float64
        )
        old_eta = self.old_x @ source_beta
        new_eta = old_eta.copy()
        if len(self.dominated_source_columns):
            dominated = self.dominated_source_columns
            new_eta -= self.old_x[:, dominated] @ source_beta[dominated]
        new_eta += float(self.added_sign) * self.new_block @ beta[self.added_slice]
        return float(
            source_evaluator.value(source_beta)
            - self._loss_sum(old_eta)
            + self._loss_sum(new_eta)
        )

    def fit_bounded(
        self,
        *,
        source_evaluator: ProjectedDesignEvaluator,
        tolerance: float,
        max_iter: int,
        nll_screen_threshold: float | None = None,
    ) -> _GradientBundleFit:
        """Solve or safely screen the child using an adaptive gradient bundle.

        The parent objective is evaluated on its resident matrix and the old
        touched likelihood is replaced by the child touched likelihood.  This
        identity is exact for both ordinary Adds and nested total-state
        splices.  Every Newton iterate contributes a global affine minorant.
        When their convex bundle proves that the optimum NLL exceeds
        ``nll_screen_threshold``, the caller may reject the Add without
        completing the fit.  A failed or nonfinite bundle always continues or
        falls open to the canonical exact solver.
        """
        beta = self.warm_beta.copy()
        nll = float(self.initial_nll)
        gradient = self.gradient.copy()
        hessian = self.hessian.copy()
        rank = 0
        cut_values: list[float] = []
        cut_coefficients: list[np.ndarray] = []
        cut_gradients: list[np.ndarray] = []
        nll_lower_bound = -math.inf
        for iteration in range(1, int(max_iter) + 1):
            if (
                not math.isfinite(nll)
                or not np.all(np.isfinite(gradient))
                or not np.all(np.isfinite(hessian))
            ):
                return _GradientBundleFit(
                    FitResult(
                        beta,
                        nll,
                        False,
                        iteration,
                        math.inf,
                        rank,
                        False,
                        "nonfinite exact matrix-free derivatives",
                    ),
                    nll_lower_bound,
                    False,
                    len(cut_values),
                )
            if not (
                cut_coefficients
                and np.array_equal(cut_coefficients[-1], beta)
                and np.array_equal(cut_gradients[-1], gradient)
            ):
                cut_values.append(float(nll))
                cut_coefficients.append(np.ascontiguousarray(beta.copy()))
                cut_gradients.append(np.ascontiguousarray(gradient.copy()))
            kkt = projected_kkt(beta, gradient, self.free_dimension)
            if kkt <= tolerance:
                critical = np.arange(self.dimension) < self.free_dimension
                critical |= beta > 1.0e-12
                critical |= gradient <= max(tolerance, 1.0e-12)
                indices = np.flatnonzero(critical)
                rank = int(np.linalg.matrix_rank(hessian[np.ix_(indices, indices)]))
                if rank < len(indices):
                    return _GradientBundleFit(
                        FitResult(
                            beta,
                            nll,
                            False,
                            iteration,
                            kkt,
                            rank,
                            False,
                            "rank-deficient exact matrix-free information",
                        ),
                        nll_lower_bound,
                        False,
                        len(cut_values),
                    )
                return _GradientBundleFit(
                    FitResult(
                        beta,
                        nll,
                        True,
                        iteration,
                        kkt,
                        rank,
                        False,
                        "exact matrix-free converged",
                    ),
                    max(nll_lower_bound, nll),
                    False,
                    len(cut_values),
                )
            active = np.arange(self.dimension) < self.free_dimension
            active |= (beta > 1.0e-12) | (gradient < 0.0)
            indices = np.flatnonzero(active)
            if not len(indices):
                return _GradientBundleFit(
                    FitResult(
                        beta,
                        nll,
                        False,
                        iteration,
                        kkt,
                        0,
                        False,
                        "empty exact matrix-free active set",
                    ),
                    nll_lower_bound,
                    False,
                    len(cut_values),
                )
            sub_hessian = hessian[np.ix_(indices, indices)]
            rank = int(np.linalg.matrix_rank(sub_hessian))
            try:
                active_direction = np.linalg.solve(sub_hessian, -gradient[indices])
            except np.linalg.LinAlgError:
                active_direction = np.linalg.lstsq(
                    sub_hessian, -gradient[indices], rcond=None
                )[0]
            direction = np.zeros(self.dimension, dtype=np.float64)
            direction[indices] = active_direction
            if float(gradient @ direction) >= 0.0:
                direction = -gradient
                direction[self.free_dimension :] = np.where(
                    (beta[self.free_dimension :] <= 1.0e-12)
                    & (direction[self.free_dimension :] < 0.0),
                    0.0,
                    direction[self.free_dimension :],
                )
            accepted = False
            previous_nll = nll
            for step_power in range(60):
                step = math.ldexp(1.0, -step_power)
                trial = beta + step * direction
                trial[self.free_dimension :] = np.maximum(
                    trial[self.free_dimension :], 0.0
                )
                trial_nll = self._value(trial, source_evaluator)
                displacement = trial - beta
                if math.isfinite(trial_nll) and trial_nll <= (
                    nll + 1.0e-4 * float(gradient @ displacement)
                ):
                    beta = trial
                    nll = trial_nll
                    accepted = True
                    break
            if not accepted:
                return _GradientBundleFit(
                    FitResult(
                        beta,
                        nll,
                        False,
                        iteration,
                        kkt,
                        rank,
                        False,
                        "exact matrix-free line search failed",
                    ),
                    nll_lower_bound,
                    False,
                    len(cut_values),
                )
            nll, gradient, hessian = self._objective(beta, source_evaluator)
            # The accepted Newton point may itself close the dual bundle.  It
            # would normally be appended at the top of the next iteration,
            # but the objective/KKT convergence return below can occur first.
            # Add and test that tangent here so a valid screen is never lost
            # merely because the primal solver converged in this iteration.
            if (
                nll_screen_threshold is not None
                and len(cut_values) >= self.free_dimension + 1
                # Once this feasible primal point already beats the incumbent
                # NLL threshold, no lower bound can reject the candidate.
                # Skipping the LP is exact and removes all racing overhead on
                # genuinely competitive Adds.
                and nll > float(nll_screen_threshold)
            ):
                cut_values.append(float(nll))
                cut_coefficients.append(np.ascontiguousarray(beta.copy()))
                cut_gradients.append(np.ascontiguousarray(gradient.copy()))
                candidate_lower = _gradient_bundle_lower_bound(
                    cut_values,
                    cut_coefficients,
                    cut_gradients,
                    free_dimension=self.free_dimension,
                )
                nll_lower_bound = max(nll_lower_bound, candidate_lower)
                decision_slack = 1.0e-9 * max(
                    1.0,
                    abs(float(nll_screen_threshold)),
                    abs(nll_lower_bound) if math.isfinite(nll_lower_bound) else 1.0,
                )
                if (
                    math.isfinite(nll_lower_bound)
                    and nll_lower_bound >= float(nll_screen_threshold) + decision_slack
                ):
                    return _GradientBundleFit(
                        FitResult(
                            beta,
                            nll,
                            False,
                            iteration,
                            projected_kkt(beta, gradient, self.free_dimension),
                            rank,
                            False,
                            "certified gradient-bundle non-improving Add",
                        ),
                        nll_lower_bound,
                        True,
                        len(cut_values),
                    )
            if abs(previous_nll - nll) <= tolerance * max(1.0, abs(previous_nll)):
                final_kkt = projected_kkt(beta, gradient, self.free_dimension)
                if final_kkt <= 10.0 * tolerance:
                    critical = np.arange(self.dimension) < self.free_dimension
                    critical |= beta > 1.0e-12
                    critical |= gradient <= max(10.0 * tolerance, 1.0e-12)
                    indices = np.flatnonzero(critical)
                    rank = int(np.linalg.matrix_rank(hessian[np.ix_(indices, indices)]))
                    if rank == len(indices):
                        return _GradientBundleFit(
                            FitResult(
                                beta,
                                nll,
                                True,
                                iteration,
                                final_kkt,
                                rank,
                                False,
                                "exact matrix-free converged by objective and KKT",
                            ),
                            max(nll_lower_bound, nll),
                            False,
                            len(cut_values),
                        )
        return _GradientBundleFit(
            FitResult(
                beta,
                nll,
                False,
                int(max_iter),
                projected_kkt(beta, gradient, self.free_dimension),
                rank,
                False,
                "exact matrix-free maximum iterations reached",
            ),
            nll_lower_bound,
            False,
            len(cut_values),
        )

    def fit_exact(
        self,
        *,
        source_evaluator: ProjectedDesignEvaluator,
        tolerance: float,
        max_iter: int,
    ) -> FitResult:
        """Solve the canonical child cone problem without its dense matrix."""

        return self.fit_bounded(
            source_evaluator=source_evaluator,
            tolerance=tolerance,
            max_iter=max_iter,
        ).fit

    def one_step_nll(self, tolerance: float) -> float | None:
        """Return the ordinary feasible one-step NLL without a target matrix.

        ``None`` is deliberately fail-open: the caller materializes the
        canonical target matrix and runs the existing validator.
        """

        beta = self.warm_beta.copy()
        gradient = self.gradient
        hessian = self.hessian
        nll = float(self.initial_nll)
        if not (
            math.isfinite(nll)
            and np.all(np.isfinite(gradient))
            and np.all(np.isfinite(hessian))
        ):
            return None
        initial_kkt = projected_kkt(beta, gradient, self.free_dimension)
        if initial_kkt <= tolerance:
            return nll
        active = np.arange(self.dimension) < self.free_dimension
        active |= (beta > 1.0e-12) | (gradient < 0.0)
        indices = np.flatnonzero(active)
        if not len(indices):
            return nll
        sub_hessian = hessian[np.ix_(indices, indices)]
        try:
            active_direction = np.linalg.solve(sub_hessian, -gradient[indices])
        except np.linalg.LinAlgError:
            active_direction = np.linalg.lstsq(
                sub_hessian, -gradient[indices], rcond=None
            )[0]
        direction = np.zeros(self.dimension, dtype=np.float64)
        direction[indices] = active_direction
        if float(gradient @ direction) >= 0.0:
            direction = -gradient
            direction[self.free_dimension :] = np.where(
                (beta[self.free_dimension :] <= 1.0e-12)
                & (direction[self.free_dimension :] < 0.0),
                0.0,
                direction[self.free_dimension :],
            )
        if not np.all(np.isfinite(direction)):
            return None

        source_direction = direction[self.source_to_target]
        old_delta_eta = self.old_x @ source_direction
        new_delta_eta = self.old_x @ source_direction
        if len(self.dominated_source_columns):
            dominated = self.dominated_source_columns
            new_delta_eta -= self.old_x[:, dominated] @ source_direction[dominated]
        new_delta_eta += (
            float(self.added_sign) * self.new_block @ direction[self.added_slice]
        )
        step = 1.0
        for _ in range(60):
            trial = beta + step * direction
            trial[self.free_dimension :] = np.maximum(trial[self.free_dimension :], 0.0)
            # Projection can alter the nominal direction at a boundary.
            displacement = trial - beta
            if np.array_equal(displacement, step * direction):
                old_step = step * old_delta_eta
                new_step = step * new_delta_eta
            else:
                projected_direction = displacement[self.source_to_target]
                old_step = self.old_x @ projected_direction
                new_step = self.old_x @ projected_direction
                if len(self.dominated_source_columns):
                    dominated = self.dominated_source_columns
                    new_step -= (
                        self.old_x[:, dominated] @ projected_direction[dominated]
                    )
                new_step += (
                    float(self.added_sign)
                    * self.new_block
                    @ displacement[self.added_slice]
                )
            source_value = self._source_value(
                self.warm_beta[self.source_to_target]
                + displacement[self.source_to_target]
            )
            trial_nll = (
                source_value
                - self._loss_sum(self.old_eta + old_step)
                + self._loss_sum(self.new_eta + new_step)
            )
            if math.isfinite(trial_nll) and trial_nll <= (
                nll + 1.0e-4 * float(gradient @ displacement)
            ):
                return float(trial_nll)
            step *= 0.5
        return None


@dataclass(frozen=True)
class _ConditionalProposal:
    """One feasible full-support Newton step and its exact-optimum sandwich."""

    record: SupportRecord
    lower_score: float
    upper_score: float
    certificate: DualCertificate | None
    matched_branch_net: float = math.inf

    @property
    def score_gap(self) -> float:
        return max(0.0, float(self.upper_score - self.lower_score))


@dataclass(frozen=True)
class _FactorizedConditionalProposal:
    """Matrix-free feasible add step, materialized only if it wins."""

    support: Support
    fit: FitResult
    penalty: float
    lower_score: float
    upper_score: float
    certificate: DualCertificate | None = None
    deferred_state: _DeferredFactorizedAddState | None = None
    matched_branch_net: float = math.inf
    projection_only: bool = False

    @property
    def score_gap(self) -> float:
        return max(0.0, float(self.upper_score - self.lower_score))


@dataclass(frozen=True)
class _ConditionalAudit:
    lower_score: float
    upper_score: float
    certificate_feasible: bool
    projected_kkt: float
    branch_net: float | None = None


@dataclass(frozen=True)
class _IdentityCandidate:
    """Compact support-conditioned W/sign proposal.

    Factorized proposals contain only coefficients and scalar certificates.
    Their observation-sized matrix is built only if the proposal wins the
    node-wide identity comparison.  ``old_rule`` is ``None`` for a same-W sign
    projection from the current support and identifies the reduced base for a
    different-W replacement.
    """

    rule: RuleIdentity
    trial: Support
    lower_score: float
    upper_score: float
    certificate_feasible: bool
    projected_kkt: float
    old_rule: RuleIdentity | None
    proposal: _FactorizedConditionalProposal | None = None
    record: SupportRecord | None = None

    @property
    def ordering_score(self) -> float:
        return (
            self.record.discovery_score if self.record is not None else self.lower_score
        )


@dataclass(frozen=True)
class _StateSpliceRelaxationState:
    """Small current-node summary used by the conditional splice bound."""

    outside_group: int
    group_nll: np.ndarray
    total_nll: float

    @property
    def nbytes(self) -> int:
        return int(self.group_nll.nbytes + 64)


@dataclass(frozen=True)
class _InformativeGroupRelaxationState:
    """Mixed parent groups sufficient for a matrix-free Add bound."""

    group_map: np.ndarray
    exposure: np.ndarray
    noevent: np.ndarray
    event: np.ndarray


class _WeightedSemaphore:
    """FIFO-agnostic byte budget for exact concurrent pricing tasks."""

    def __init__(self, capacity: int):
        self.capacity = max(1, int(capacity))
        self._used = 0
        self.peak = 0
        self._condition = threading.Condition()

    def acquire(self, amount: int) -> int:
        reserved = min(self.capacity, max(1, int(amount)))
        with self._condition:
            while self._used and self._used + reserved > self.capacity:
                self._condition.wait()
            self._used += reserved
            self.peak = max(self.peak, self._used)
        return reserved

    def release(self, reserved: int) -> None:
        with self._condition:
            self._used -= int(reserved)
            if self._used < 0:
                raise AssertionError("pricing memory reservation underflow")
            self._condition.notify_all()


class _TerminalPointerCache:
    """Byte-bounded support-to-terminal pointers for exact DAG compression.

    Values contain no fitted coefficients or response matrices.  Eviction only
    removes an acceleration hint; the exact search recomputes the path if that
    support is reached again.
    """

    def __init__(self, limit: int):
        self.limit = max(0, int(limit))
        self._entries: OrderedDict[Support, Support] = OrderedDict()
        self.nbytes = 0
        self.peak_bytes = 0
        self.evictions = 0
        self.conflicts = 0

    @staticmethod
    def entry_bytes(source: Support, target: Support) -> int:
        # Conservative ownership accounting for dictionary slots, tuple keys,
        # identity references and hash-table slack.  Immutable RuleIdentity
        # objects are shared with the finite dictionary and are not owned here.
        return 256 + 64 * (len(source.rules) + len(target.rules))

    def get(self, source: Support) -> Support | None:
        target = self._entries.pop(source, None)
        if target is not None:
            self._entries[source] = target
        return target

    def remember(self, source: Support, target: Support) -> bool:
        previous = self._entries.pop(source, None)
        if previous is not None:
            if previous != target:
                # Provisional coefficient states are route dependent.  A
                # conflicting terminal pointer is only an acceleration hint;
                # preserve the first deterministic mapping and continue.
                self._entries[source] = previous
                self.conflicts += 1
                return False
            self.nbytes -= self.entry_bytes(source, previous)
        required = self.entry_bytes(source, target)
        if required > self.limit:
            # An unusually large single support is simply not compressed.
            # Keeping no pointer is preferable to violating the hard budget.
            self.evictions += 1
            return False
        while self._entries and self.nbytes + required > self.limit:
            evicted_source, evicted_target = self._entries.popitem(last=False)
            self.nbytes -= self.entry_bytes(evicted_source, evicted_target)
            self.evictions += 1
        self._entries[source] = target
        self.nbytes += required
        self.peak_bytes = max(self.peak_bytes, self.nbytes)
        return True


def _available_memory_bytes() -> int | None:
    """Best-effort physical-memory availability without an optional package."""
    try:
        pages = int(os.sysconf("SC_AVPHYS_PAGES"))
        page_size = int(os.sysconf("SC_PAGE_SIZE"))
    except (OSError, TypeError, ValueError):
        return None
    return pages * page_size if pages > 0 and page_size > 0 else None


