@dataclass(frozen=True)
class SearchResult:
    family: tuple[SupportRecord, ...]
    terminals: tuple[SupportRecord, ...]
    positive_atoms: tuple[SupportRecord, ...]
    compact_candidates: tuple[SupportRecord, ...]
    paths: tuple[dict[str, object], ...]
    diagnostics: SearchDiagnostics


class _PatternWindowDictionary(dict[PatternKey, tuple[int, ...]]):
    """Relation-explicit storage with read-only legacy antecedent lookup.

    Iteration and serialization always expose v13 ``PatternKey`` values.  The
    compatibility lookup prevents older fixed-support callers from silently
    selecting a different window dictionary during the schema transition.
    """

    @staticmethod
    def _key(value: object) -> object:
        if isinstance(value, tuple):
            try:
                return normalize_pattern(value)  # type: ignore[arg-type]
            except (TypeError, ValueError):
                return value
        return value

    def __getitem__(self, key: object) -> tuple[int, ...]:
        return super().__getitem__(self._key(key))

    def get(
        self,
        key: object,
        default: tuple[int, ...] | None = None,
    ) -> tuple[int, ...] | None:
        return super().get(self._key(key), default)

    def __contains__(self, key: object) -> bool:
        return super().__contains__(self._key(key))


class _PatternSet(set[PatternKey]):
    """Internal PatternKey set with legacy antecedent equality/lookup."""

    @staticmethod
    def _key(value: object) -> object:
        if isinstance(value, tuple):
            try:
                return normalize_pattern(value)  # type: ignore[arg-type]
            except (TypeError, ValueError):
                return value
        return value

    def __contains__(self, value: object) -> bool:
        return super().__contains__(self._key(value))

    def add(self, value: PatternKey | Antecedent) -> None:
        super().add(normalize_pattern(value))

    def update(self, *others: Iterable[PatternKey | Antecedent]) -> None:
        for other in others:
            for value in other:
                self.add(value)

    def __eq__(self, other: object) -> bool:
        if isinstance(other, (set, frozenset, _PatternSet)):
            try:
                normalized = {normalize_pattern(value) for value in other}
            except (TypeError, ValueError):
                return False
            return set.__eq__(self, normalized)
        return False


class _ProfiledPatternDictionary(_PatternWindowDictionary):
    """Legacy inspection view over relation-explicit profiled identities."""

    def __iter__(self):
        for pattern in dict.__iter__(self):
            yield pattern[1]

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, dict):
            return False
        try:
            normalized = {normalize_pattern(key): value for key, value in other.items()}
        except (TypeError, ValueError):
            return False
        return dict.__eq__(self, normalized)


class _ProfiledSignDictionary(dict[tuple[PatternKey, int], RuleIdentity]):
    """Legacy iterator over relation-explicit directional profile keys."""

    def __iter__(self):
        for pattern, sign in dict.__iter__(self):
            yield pattern[1], sign


@dataclass(frozen=True)
class _MoveDecision:
    """One monotone move from a canonically backward-reduced support.

    A non-null ``record`` with ``drop_stable=False`` is an improving Drop and
    must be applied before any other coordinate is considered.  Once
    ``drop_stable`` is true, every active rule has passed the same conditional
    Drop audit; a same-size record is an identity replacement and a larger
    record is an Add.
    """

    record: SupportRecord | None
    drop_stable: bool


