class _HierarchyRuleGeometry:
    gradient: np.ndarray
    hessian: np.ndarray
    nested: bool
    joint_gradient: np.ndarray | None = None
    joint_hessian: np.ndarray | None = None
    current_cross: np.ndarray | None = None
    closure_dimension: int = 0
    profile_valid: bool = True

    @property
    def nbytes(self) -> int:
        return int(
            self.gradient.nbytes
            + self.hessian.nbytes
            + (0 if self.joint_gradient is None else self.joint_gradient.nbytes)
            + (0 if self.joint_hessian is None else self.joint_hessian.nbytes)
            + (0 if self.current_cross is None else self.current_cross.nbytes)
        )


